trait BookingGateway[F[_]] {                    // domestic interface
  def slots(len: FiniteDuration): F[List[Slot]]
}

final class HttpBookingGateway[F[_]: Concurrent](client: Client[F], base: Uri)
    extends BookingGateway[F] {
  def slots(len: FiniteDuration): F[List[Slot]] =
    client.expect[List[ForeignSlot]](base / "slots" +? ("minutes" -> len.toMinutes.toString))
      .map(_.map(_.toSlot))                       // foreign -> domestic
}

