final class BookingGateway(client: java.net.http.HttpClient, base: URI) {
  def slots(len: Duration): Try[List[Slot]] = Try {
    val req = HttpRequest.newBuilder(base.resolve("/slots")).GET().build()
    val res = client.send(req, HttpResponse.BodyHandlers.ofString())
    if (res.statusCode() / 100 != 2) throw new GatewayException(res.statusCode())
    decodeForeign(res.body()).map(_.toSlot)        // foreign -> domestic
  }
}
